function validate(input) {
  const [{ Orders = [] }] = input;
  const seen = new Set();
  for (const [id, customer, date, price] of Orders) {
    if (id === null || customer === null || date === null || price === null) return 'Orders rows may not contain null.';
    if (seen.has(id)) return `order_id ${id} appears twice.`;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return `order_date ${date} is not a date.`;
    if (price <= 0) return `Order ${id} must have a positive price.`;
    seen.add(id);
  }
  return null;
}

