function generate(rand, size) {
  const small = size === 'small';
  const pad = v => String(v).padStart(2, '0');
  const date = year => `${year}-${pad(1 + Math.floor(rand() * 12))}-${pad(1 + Math.floor(rand() * 28))}`;
  const limit = small ? 8 : 2000;
  const customers = small ? Math.floor(rand() * 4) : 400;
  const Orders = [];
  for (let customer = 1; customer <= customers && Orders.length < limit; customer++) {
    const years = 1 + Math.floor(rand() * (small ? 3 : 5));
    const start = 2016 + Math.floor(rand() * 5);
    const flaw = rand();
    const totals = [];
    let total = small ? 100 * (1 + Math.floor(rand() * 4)) : 1 + Math.floor(rand() * 500);
    for (let i = 0; i < years; i++) {
      totals.push(total);
      total += small ? 100 * Math.floor(rand() * 3) + (rand() < 0.7 ? 100 : 0) : Math.floor(rand() * 300) - (rand() < 0.15 ? 200 : -1);
      if (total < 1) total = 1;
    }
    // Usually strictly increasing; sometimes a skipped year or a repeated total breaks it.
    let year = start;
    totals.forEach((value, i) => {
      if (i > 0 && flaw < 0.15) year += 1;
      if (i > 0 && flaw > 0.85 && i === years - 1) value = totals[i - 1];
      const parts = value >= 2 && rand() < 0.4 ? [Math.floor(value / 3) || 1] : [];
      if (parts.length) parts.push(value - parts[0]); else parts.push(value);
      for (const price of parts) if (Orders.length < limit) Orders.push([0, customer, date(year), price]);
      year++;
    });
  }
  for (let i = Orders.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Orders[i], Orders[j]] = [Orders[j], Orders[i]]; }
  Orders.forEach((row, i) => { row[0] = i + 1; });
  return [{ Orders }];
}
